  'use strict';
  // Nightly. For each agent: how many ratings their tickets received in the past seven days, and the average.
  // An agent with no ratings gets no row. A ticket with no owner counts for nobody.
  const WINDOW_DAYS = 7;
  const DAY = 24 * 60 * 60 * 1000;

  function weeklyAgentSummary(store, { now = new Date() } = {}) {
    const since = now.getTime() - WINDOW_DAYS * DAY;
    const scores = new Map();
    for (const t of store.listTickets()) {
      if (t.rating == null || !t.owner_id) continue;
      if (new Date(t.rated_at).getTime() < since) continue;
      if (!scores.has(t.owner_id)) scores.set(t.owner_id, []);
      scores.get(t.owner_id).push(t.rating);
    }
    const week_ending = now.toISOString().slice(0, 10);
    const rows = [...scores].map(([agent_id, list]) => ({
      agent_id,
      week_ending,
      ratings: list.length,
      average: Math.round((list.reduce((a, b) => a + b, 0) / list.length) * 100) / 100,
    }));
    rows.forEach((row) => store.saveAgentSummary(row));
    return rows;
  }

  module.exports = { weeklyAgentSummary, WINDOW_DAYS };
  ```
